CREATE TEMPORARY VIEW user_order_history_${grass_region_without_quote} AS
SELECT
    user_id,
    array_sort(
        collect_list(
            named_struct(
                "local_date",
                local_date,
                "order_cnt",
                order_cnt,
                "gmv",
                gmv
            )
        )
        ,
        (left, right) -> case when left.local_date < right.local_date then -1 when left.local_date > right.local_date then 1 else 0 end
    ) AS place_order_history
FROM
(
    SELECT
        user_id,
        local_date,
        sum(operation_cnt) AS order_cnt,
        sum(place_order_gmv) AS gmv
    FROM
        srdi_mart.dwd_sr_data_warehouse_platform
    WHERE
        local_date BETWEEN date_sub(${local_date}, 90) AND date_sub(${local_date}, 1)
        AND grass_region IN (${grass_region})
        AND operation = 'order'
        AND feature_detail IN ('global_search-item', 'search_in_pdp-item')
    GROUP BY 
        user_id,
        local_date
)
GROUP BY
    user_id;

--sql_divide_splitter--

CREATE TEMPORARY VIEW user_rfm_updated_${grass_region_without_quote} AS
SELECT
    user_id,
    place_order_history,
    named_struct(
        "recency",
        coalesce(datediff(${local_date}, element_at(place_order_history, -1).local_date), 90),
        "frequency",
        coalesce(aggregate(place_order_history, cast(0 AS DOUBLE), (acc, x) -> acc + x.order_cnt), 0),
        "monetary_value",
        coalesce(aggregate(place_order_history, cast(0 AS DOUBLE), (acc, x) -> acc + x.gmv), 0)
    ) AS rfm
FROM
    user_order_history_${grass_region_without_quote};

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_search_user_rfm_1d
PARTITION (
    grass_region = ${grass_region},
    local_date = ${local_date}
)
SELECT
    user_id,
    place_order_history,
    named_struct(
        "recency",
        rfm.recency,
        "recency_type",
        CASE 
            WHEN ${grass_region} = 'ID' AND rfm.recency <= 7 THEN 'High'
            WHEN ${grass_region} = 'ID' AND 8 <= rfm.recency AND rfm.recency <= 30 THEN 'Medium'
            WHEN ${grass_region} = 'ID' AND 31 <= rfm.recency AND rfm.recency <= 90 THEN 'Low'
            WHEN ${grass_region} = 'BR' AND rfm.recency <= 12 THEN 'High'
            WHEN ${grass_region} = 'BR' AND 13 <= rfm.recency AND rfm.recency <= 50 THEN 'Medium'
            WHEN ${grass_region} = 'BR' AND 51 <= rfm.recency AND rfm.recency <= 90 THEN 'Low'
        END,
        "frequency",
        rfm.frequency,
        "frequency_type",
        CASE 
            WHEN ${grass_region} = 'ID' AND rfm.frequency > 30 THEN 'High'
            WHEN ${grass_region} = 'ID' AND 12 < rfm.frequency AND rfm.frequency <= 30 THEN 'Medium'
            WHEN ${grass_region} = 'ID' AND rfm.frequency <= 12 THEN 'Low'
            WHEN ${grass_region} = 'BR' AND rfm.frequency > 7 THEN 'High'
            WHEN ${grass_region} = 'BR' AND 2 < rfm.frequency AND rfm.frequency <= 7 THEN 'Medium'
            WHEN ${grass_region} = 'BR' AND  rfm.frequency <= 2 THEN 'Low'
        END,
        "monetary_value",
        rfm.monetary_value,
        "monetary_value_type",
        CASE 
            WHEN ${grass_region} = 'ID' AND rfm.monetary_value > 140 THEN 'High'
            WHEN ${grass_region} = 'ID' AND 60 < rfm.monetary_value AND rfm.monetary_value <= 140 THEN 'Medium'
            WHEN ${grass_region} = 'ID' AND rfm.monetary_value <= 60 THEN 'Low'
            WHEN ${grass_region} = 'BR' AND rfm.monetary_value > 90 THEN 'High'
            WHEN ${grass_region} = 'BR' AND 25 < rfm.monetary_value AND rfm.monetary_value <= 90 THEN 'Medium'
            WHEN ${grass_region} = 'BR' AND rfm.monetary_value <= 25 THEN 'Low'
        END
    )
FROM user_rfm_updated_${grass_region_without_quote};

