CREATE TEMPORARY VIEW user_search_order_history_${grass_region_without_quote} AS
SELECT
    user_id,
    array_sort(
        collect_list(
            struct(
                local_date,
                order_cnt,
                gmv
            )
        ) 
    ,
    (left, right) -> case when left.local_date < right.local_date then -1 when left.local_date > right.local_date then 1 else 0 end
    ) AS place_order_history
FROM
(
    SELECT
        user_id,
        local_date,
        sum(operation_cnt) AS order_cnt,
        sum(place_order_gmv) AS gmv
    FROM
        srdi_mart.dwd_sr_data_warehouse_platform
    WHERE
        local_date BETWEEN date_sub(${local_date}, 90) AND ${local_date}
        AND grass_region IN (${grass_region})
        AND operation = 'order'
        AND feature_detail IN ('global_search-item', 'search_in_pdp-item')
    GROUP BY 
        user_id,
        local_date
)
GROUP BY
    user_id;

--sql_divide_splitter--

CREATE TEMPORARY VIEW user_rfm_${grass_region_without_quote} AS
SELECT
    user_id,
    place_order_history,
    named_struct(
        "recency",
        coalesce(datediff(${local_date}, element_at(filter(place_order_history, x -> x.local_date < ${local_date}), -1).local_date), 90), -- for users without orders in the last 90 days, mark recency as 90
        "frequency",
        coalesce(aggregate(filter(place_order_history, x -> x.local_date < ${local_date}), cast(0 AS DOUBLE), (acc, x) -> acc + x.order_cnt), 0),
        "monetary_value",
        coalesce(aggregate(filter(place_order_history, x -> x.local_date < ${local_date}), cast(0 AS DOUBLE), (acc, x) -> acc + x.gmv), 0)
    ) AS rfm
FROM
    user_search_order_history_${grass_region_without_quote};

